/** Shapes of the bundled endpoint catalog (catalog/endpoints.json), generated by scripts/sync-docs.ts. */

export interface Field {
  name: string;
  type: string;
  required: boolean;
  description: string;
  /** OpenAPI format, e.g. guid or date-time. */
  format?: string;
  /** Allowed values, from the spec's enum or the "Can have the following values" list in the description. */
  enum?: string[];
  fields?: Field[];
}

export type ParamIn = "path" | "query" | "body";

export interface Param extends Field {
  in: ParamIn;
}

export interface Endpoint {
  /** Stable id made from the docs summary, e.g. "list-of-administrations". */
  id: string;
  /** Docs section (OpenAPI tag), e.g. "Administrations". */
  group: string;
  method: "GET" | "POST" | "PUT" | "DELETE" | "PATCH";
  path: string;
  summary: string;
  description: string;
  deprecated: boolean;
  params: Param[];
  response: Field[];
}

export interface Catalog {
  source: string;
  syncedAt: string;
  endpoints: Endpoint[];
}
